package io.knowledgebrain.learning;
import java.util.*;import java.time.Clock;import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class RoadmapRatingApiTest {
 RoadmapRatingStore store;SpaceAuthorizationClient authority;RoadmapRatingController api;UUID space,id,actor;
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();id=ids.next();actor=ids.next();store=mock(RoadmapRatingStore.class);authority=mock(SpaceAuthorizationClient.class);var metrics=new SimpleMeterRegistry();api=new RoadmapRatingController(store,authority,new RoadmapController(mock(RoadmapStore.class),authority,metrics,"https://localhost:8443"),metrics,"https://localhost:8443");when(authority.authorize(eq(space),any(),anyString(),eq("PUBLIC"),anyString())).thenReturn(actor);}
 MockHttpServletRequest r(String method,String body){var r=new MockHttpServletRequest(method,"/");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.addHeader("traceparent","00-"+"a".repeat(32)+"-"+"b".repeat(16)+"-01");r.setContentType("application/json");r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void ownRatingIsRegisteredScopedAndNoRatingUsesStrongZeroTag(){when(store.mine(space,id,actor)).thenReturn(new RoadmapRatingStore.Mine(space,id,1,true,null));assertEquals("\"rr0\"",api.get(space.toString(),id.toString(),r("GET","")).getHeaders().getETag());var order=inOrder(authority,store);order.verify(authority).authorize(eq(space),any(),eq("ROADMAP_RATING_READ"),eq("PUBLIC"),anyString());order.verify(store).mine(space,id,actor);reset(store);when(authority.authorize(eq(space),any(),anyString(),eq("PUBLIC"),anyString())).thenThrow(new ResponseStatusException(HttpStatus.FORBIDDEN));assertThrows(ResponseStatusException.class,()->api.get(space.toString(),id.toString(),r("GET","")));verifyNoInteractions(store);}
 @Test void starBodyAndStrongTagCannotSpoofActorVersionOrAcceptWeakSyntax()throws Exception{for(String body:List.of("{}","{\"roadmapVersion\":1,\"score\":4,\"principalId\":\"spoof\"}","{\"roadmapVersion\":1,\"score\":2.5}","{\"roadmapVersion\":1,\"score\":4,\"score\":5}","{\"roadmapVersion\":1,\"score\":5} {}")){var req=r("PUT",body);req.addHeader("If-Match","\"rr0\"");assertThrows(ResponseStatusException.class,()->api.put(space.toString(),id.toString(),req));}for(String tag:List.of("\"rr01\"","\"pc1\"","W/\"rr1\"","\"rr9223372036854775808\"")){var req=r("PUT","{}");req.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.put(space.toString(),id.toString(),req));}assertEquals(428,assertThrows(ResponseStatusException.class,()->api.put(space.toString(),id.toString(),r("PUT","{}"))).getStatusCode().value());verifyNoInteractions(store);}
 @Test void strictQueriesBodiesDuplicateCookiesAndForeignOriginRejectBeforeStore()throws Exception{for(String sort:List.of("AI","rating","RATING;DROP TABLE")){var req=r("GET","");req.addParameter("sort",sort);assertThrows(ResponseStatusException.class,()->api.ranking(space.toString(),req));}var duplicate=r("GET","");duplicate.addParameter("limit","1","2");assertThrows(ResponseStatusException.class,()->api.ranking(space.toString(),duplicate));assertThrows(ResponseStatusException.class,()->api.summary(space.toString(),id.toString(),r("GET","{}")));var foreign=r("PUT","{}");foreign.removeHeader("Origin");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.put(space.toString(),id.toString(),foreign)).getStatusCode().value());var body=r("DELETE","{}");body.addHeader("If-Match","\"rr1\"");assertThrows(ResponseStatusException.class,()->api.retire(space.toString(),id.toString(),body));verifyNoInteractions(store);}
}
